#include <iostream>
#include <string>
#include <utility>

// Recursive function to generate all permutations of a string
void displayPermutations(std::string s, int low, int high) {
    if (low == high) { // Base case: single character permutation reached
        std::cout << s << " ";
    } else {
        for (int i = low; i <= high; ++i) {
            std::swap(s[low], s[i]); // Choose character at position i
            displayPermutations(s, low + 1, high); // Recursive call for remainder
            std::swap(s[low], s[i]); // Backtrack to restore original order
        }
    }
}

int main() {
    std::string text = "abc";
    std::cout << "Permutations of " << text << ": ";
    displayPermutations(text, 0, static_cast<int>(text.length()) - 1);
    std::cout << "\n";
    return 0;
}

#include <iostream>

// Return the factorial for a specified non-negative integer
unsigned long long factorial(int n) {
    if (n == 0) // Base case
        return 1;
    else
        return n * factorial(n - 1); // Recursive call
}

int main() {
    int n = 5;
    std::cout << "Factorial of " << n << " is " << factorial(n) << "\n";
    return 0;
}
